import com.sun.net.httpserver.HttpServer;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;
public final class Equipment718CloudCheck {
 public static void main(String[] args)throws Exception{String id="12345678-1234-1234-1234-123456789abc";Set<String> seen=new HashSet<>();HttpServer fake=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);fake.createContext("/",x->{try{if(!"sb_secret_test".equals(x.getRequestHeaders().getFirst("apikey")))throw new AssertionError("Server-only key");String path=x.getRequestURI().getPath(),method=x.getRequestMethod();String text=new String(x.getRequestBody().readAllBytes(),StandardCharsets.UTF_8);if(path.endsWith("gunny_exchange")){Map<String,Object> body=Json.obj(Json.parse(text));if(!id.equals(body.get("p_user"))||Json.num(body,"p_amount",0)!=1||!"rpc-test".equals(body.get("p_key")))throw new AssertionError("Exchange payload");seen.add("exchange");}else if(path.endsWith("gunny_equip")){Map<String,Object> body=Json.obj(Json.parse(text));if(Json.num(body,"p_kind",-1)!=3||Json.num(body,"p_item",-1)!=2)throw new AssertionError("Equip payload");seen.add("equip");}else if(method.equals("PATCH")){Map<String,Object> body=Json.obj(Json.parse(text));if(Json.num(body,"worn_mask",0)!=9||!Boolean.TRUE.equals(body.get("custom_look")))throw new AssertionError("Appearance mask");seen.add("appearance");}String reply=method.equals("GET")?"[{\"display_name\":\"Equip\",\"gender\":0,\"skin\":0,\"custom_look\":true,\"look\":[0,2,0,0,0],\"coins\":100,\"shopping_money\":45,\"worn_mask\":9,\"wardrobe\":[1,1,5,1,1,1,1,1,1,1,1,1]}]":"";byte[] bytes=reply.getBytes(StandardCharsets.UTF_8);x.sendResponseHeaders(200,bytes.length);x.getResponseBody().write(bytes);x.close();}catch(Exception e){throw new RuntimeException(e);}});fake.start();try{CloudStore c=new CloudStore("http://127.0.0.1:"+fake.getAddress().getPort(),"sb_publishable_test","sb_secret_test",true);CloudStore.Profile p=c.exchange(id,1,"rpc-test");if(p.coins!=100||p.shoppingMoney!=45||p.wornMask!=9)throw new AssertionError("Wallet decode");p=c.equip(id,3,2);if(p.look[1]!=2||p.wornMask!=9)throw new AssertionError("Equipped response");c.appearanceEquipped(id,"Equip",0,0,true,new int[]{0,2,0,0,0},9);if(seen.size()!=3)throw new AssertionError("Missing contract");System.out.println("All equipment 7.1.8 CloudStore contracts passed");}finally{fake.stop(0);}}
}
